reference_patch.text:
diff --git a/block/blk-core.c b/block/blk-core.c
index ee33590f54eb46ae439cb9790a3b71bb3cc23d0f..4a36377df394dabf033dc29e1747eba0eb54a07a 100644
--- a/block/blk-core.c
+++ b/block/blk-core.c
@@ -1180,6 +1180,7 @@ int blk_init_allocated_queue(struct request_queue *q)
 		q->exit_rq_fn(q, q->fq->flush_rq);
 out_free_flush_queue:
 	blk_free_flush_queue(q->fq);
+	q->fq = NULL;
 	return -ENOMEM;
 }
 EXPORT_SYMBOL(blk_init_allocated_queue);

